harnesses.compare.py:
"""Paired before/after fresh-process measurements; no builds run concurrently."""
import hashlib
import json
import os
from pathlib import Path
import statistics
import subprocess
import measure as m

BASE=m.OUT
BINARIES={"before": BASE / "wyn-before.exe", "after": m.ROOT / "target/release/wyn.exe"}
os.environ.setdefault("RUST_MIN_STACK", "67108864")
os.environ.pop("WYN_EGGLOG_PROFILE", None)
records={name: {version: [] for version in BINARIES} for name in ["tinyporto-basic", "fluid"]}
assert all("-O" not in m.CASES[name] for name in records)
for version in BINARIES:
    (BASE / version).mkdir(exist_ok=True)
for index in range(6):
    order=["before", "after"] if index % 2 == 0 else ["after", "before"]
    for name in records:
        for version in order:
            m.BINARY=BINARIES[version]
            m.OUT=BASE / version
            record=m.run(name, m.CASES[name], "warmup" if index == 0 else str(index))
            if index:
                records[name][version].append(record)
summary={}
for name, versions in records.items():
    summary[name]={}
    for version, runs in versions.items():
        summary[name][version]={"runs": runs, "median_wall_ms": statistics.median(r["wall_ms"] for r in runs)}
        for key in ["coarse_ms", "timings_ms"]:
            summary[name][version]["median_"+key]={phase: statistics.median(r[key][phase] for r in runs) for phase in runs[0][key]}
    print(name, json.dumps({version: {"wall_ms": data["median_wall_ms"], "fusion_ms": data["median_timings_ms"]["egglog fusion"], "choose_ms": data["median_timings_ms"]["egglog fusion / choose"], "adjacency_ms": data["median_timings_ms"].get("egglog fusion / adjacency", 0.0)} for version, data in summary[name].items()}), flush=True)
result={"summary": summary, "binaries": {version: {"path": str(path), "sha256": hashlib.sha256(path.read_bytes()).hexdigest()} for version,path in BINARIES.items()}}
(BASE / "comparison.json").write_text(json.dumps(result, indent=2)+"\n")

